export class HomeComponent {
  constructor(auctionService, authService, wsService, router) {
    this.auctionService = auctionService;
    this.authService = authService;
    this.wsService = wsService;
    this.router = router;
    this.auctions = [];
    this.filteredAuctions = [];
    this.isLoading = true;
    this.errorMessage = '';
    this.categories = [];
    this.selectedCategory = '';
    this.minPrice = 0;
    this.maxPrice = 1000000;
    this.priceRangeMax = 1000000;
    this.timerInterval = null;
    this.timerTick = 0;
    // tracks which auctionIds just received a bid update (for flash animation)
    this.updatedBidIds = new Set();
  }
  ngOnInit() {
    this.loadAuctions();
    this.timerInterval = setInterval(() => {
      this.timerTick++;
    }, 1000);
    // Connect WebSocket for real-time home page updates
    this.wsService.connect();
    this.wsSub = this.wsService.messages$.subscribe(msg => {
      if (msg.type === 'AUCTION_STARTED' && msg.auctionId) {
        const auction = this.auctions.find(a => a.auctionId === msg.auctionId);
        if (auction) {
          auction.status = 'LIVE';
          this.applyFilters();
        }
      } else if (msg.type === 'AUCTION_STOPPED' && msg.auctionId) {
        const auction = this.auctions.find(a => a.auctionId === msg.auctionId);
        if (auction) {
          auction.status = 'ENDED';
          this.applyFilters();
        }
      } else if (!msg.type && msg.auctionId && msg.amount) {
        // Regular bid update
        const auction = this.auctions.find(a => a.auctionId === msg.auctionId);
        if (auction && msg.amount > auction.currentBid) {
          auction.currentBid = msg.amount;
          if (msg.highestBidder) auction.highestBidder = msg.highestBidder;
          // Flash animation
          this.updatedBidIds.add(msg.auctionId);
          setTimeout(() => {
            this.updatedBidIds.delete(msg.auctionId);
          }, 1200);
          this.applyFilters();
        }
      }
    });
  }
  loadAuctions() {
    this.isLoading = true;
    this.errorMessage = '';
    this.auctionService.getFeaturedAuctions().subscribe({
      next: data => {
        this.auctions = data;
        const catSet = new Set();
        data.forEach(a => {
          if (a.product?.category?.categoryName) catSet.add(a.product.category.categoryName);
        });
        this.categories = Array.from(catSet);
        const prices = data.map(a => a.currentBid || a.product.startingPrice).filter(p => p > 0);
